// The console object.

use super::{display_value, write_stderr, write_stdout};
use crate::object::*;
use crate::value::*;
use crate::vm::{JsResult, Vm};

pub fn setup(vm: &mut Vm) {
    let c = vm.new_object();
    let methods: &[(&str, NativeFn)] = &[
        ("log", log),
        ("info", log),
        ("debug", log),
        ("warn", warn),
        ("error", warn),
        ("dirxml", log),
        ("dir", dir),
        ("trace", trace),
        ("assert", assert),
        ("clear", noop),
        ("count", count),
        ("countReset", count_reset),
        ("group", group),
        ("groupCollapsed", group),
        ("groupEnd", noop),
        ("time", time),
        ("timeEnd", time_end),
        ("timeLog", time_log),
        ("timeStamp", noop),
        ("profile", noop),
        ("profileEnd", noop),
        ("table", table),
        ("createTask", create_task),
    ];
    for (n, f) in methods {
        let fo = vm.native_fn(n, 0, *f);
        c.set_prop(PropKey::from_str(n), Value::Obj(fo), WEC);
    }
    let cc = vm.native_fn("Console", 1, console_ctor);
    vm.make_ctor(&cc);
    let cp = vm.new_object();
    cc.set_prop(vm.intr.key_prototype.clone(), Value::Obj(cp.clone()), 0);
    cp.set_prop(vm.intr.key_constructor.clone(), Value::Obj(cc.clone()), WC);
    c.set_prop(PropKey::from_str("Console"), Value::Obj(cc), WEC);
    let ctx = vm.native_fn("context", 1, context);
    c.set_prop(PropKey::from_str("context"), Value::Obj(ctx), WEC);
    vm.def_global("console", Value::Obj(c));
}

fn fmt_args(vm: &mut Vm, args: &[Value]) -> String {
    let parts: Vec<String> = args.iter().map(|v| display_value(vm, v)).collect();
    parts.join(" ")
}

fn log(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let s = fmt_args(vm, a.args);
    write_stdout(vm, &format!("{}\n", s));
    Ok(Value::Undefined)
}

fn warn(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let s = fmt_args(vm, a.args);
    write_stderr(&format!("{}\n", s));
    Ok(Value::Undefined)
}

fn noop(_vm: &mut Vm, _a: &Args) -> JsResult<Value> {
    Ok(Value::Undefined)
}

fn group(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    if !a.args.is_empty() {
        let s = fmt_args(vm, a.args);
        write_stdout(vm, &format!("{}\n", s));
    }
    Ok(Value::Undefined)
}

fn dir(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let s = super::util::inspect_with_options(vm, &a.arg(0), &a.arg(1))?;
    write_stdout(vm, &format!("{}\n", s));
    Ok(Value::Undefined)
}

fn trace(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let msg = fmt_args(vm, a.args);
    let mut s = if a.args.is_empty() { "Trace".to_string() } else { format!("Trace: {}", msg) };
    s.push_str("\n    at trace");
    for e in vm.trace.iter().rev() {
        s.push_str("\n    at ");
        s.push_str(&e.name.to_rust_string());
    }
    write_stderr(&format!("{}\n", s));
    Ok(Value::Undefined)
}

fn assert(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    if a.arg(0).truthy() {
        return Ok(Value::Undefined);
    }
    let rest = if a.args.len() > 1 { &a.args[1..] } else { &[][..] };
    if rest.is_empty() {
        write_stderr("Assertion failed\n");
    } else {
        let s = fmt_args(vm, rest);
        write_stderr(&format!("Assertion failed: {}\n", s));
    }
    Ok(Value::Undefined)
}

fn label_of(vm: &mut Vm, v: &Value) -> JsResult<String> {
    if v.is_undefined() {
        Ok("default".to_string())
    } else {
        Ok(vm.to_string(v)?.to_rust_string())
    }
}

fn count(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let l = label_of(vm, &a.arg(0))?;
    let c = vm.host.console_counts.entry(l.clone()).or_insert(0);
    *c += 1;
    let n = *c;
    write_stdout(vm, &format!("{}: {}\n", l, n));
    Ok(Value::Undefined)
}

fn count_reset(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let l = label_of(vm, &a.arg(0))?;
    if let Some(c) = vm.host.console_counts.get_mut(&l) {
        *c = 0;
    }
    Ok(Value::Undefined)
}

fn time(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let l = label_of(vm, &a.arg(0))?;
    vm.host.console_timers.insert(l, std::time::Instant::now());
    Ok(Value::Undefined)
}

fn fmt_elapsed(d: std::time::Duration) -> String {
    let ms = d.as_secs_f64() * 1000.0;
    if ms >= 1000.0 {
        format!("{:.3}s", ms / 1000.0)
    } else {
        format!("{:.3}ms", ms)
    }
}

fn time_end(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let l = label_of(vm, &a.arg(0))?;
    match vm.host.console_timers.remove(&l) {
        Some(t) => {
            let s = format!("{}: {}\n", l, fmt_elapsed(t.elapsed()));
            write_stdout(vm, &s);
        }
        None => write_stderr(&format!("Warning: No such label '{}' for console.timeEnd()\n", l)),
    }
    Ok(Value::Undefined)
}

fn time_log(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let l = label_of(vm, &a.arg(0))?;
    match vm.host.console_timers.get(&l) {
        Some(t) => {
            let mut s = format!("{}: {}", l, fmt_elapsed(t.elapsed()));
            if a.args.len() > 1 {
                s.push(' ');
                s.push_str(&fmt_args(vm, &a.args[1..]));
            }
            write_stdout(vm, &format!("{}\n", s));
        }
        None => write_stderr(&format!("Warning: No such label '{}' for console.timeLog()\n", l)),
    }
    Ok(Value::Undefined)
}

fn create_task(vm: &mut Vm, _a: &Args) -> JsResult<Value> {
    let o = vm.new_object();
    let run = vm.native_fn("run", 1, |vm, a| vm.call(&a.arg(0), Value::Undefined, &[]));
    o.set_str("run", Value::Obj(run), WEC);
    Ok(Value::Obj(o))
}

fn context(vm: &mut Vm, _a: &Args) -> JsResult<Value> {
    let c = vm.global.get_own_str("console").unwrap_or(Value::Undefined);
    Ok(c)
}

fn console_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    // new Console(stdout, stderr) / new Console({stdout, stderr})
    let first = a.arg(0);
    let (out, err) = if let Value::Obj(o) = &first {
        let w = vm.get_str(o, "write")?;
        if w.is_callable() {
            let e = if a.arg(1).is_undefined() { first.clone() } else { a.arg(1) };
            (first.clone(), e)
        } else {
            let so = vm.get_str(o, "stdout")?;
            let se = vm.get_str(o, "stderr")?;
            let se = if se.is_undefined() { so.clone() } else { se };
            (so, se)
        }
    } else {
        (first.clone(), a.arg(1))
    };
    let ok = match &out {
        Value::Obj(o) => vm.get_str(o, "write")?.is_callable(),
        _ => false,
    };
    if !ok {
        return vm.throw_type("The \"stdout\" argument must be an instance of a writable stream");
    }
    let c = vm.new_object();
    for (n, which) in [("log", 0), ("info", 0), ("debug", 0), ("warn", 1), ("error", 1)] {
        let target = if which == 0 { out.clone() } else { err.clone() };
        let f = vm.native_closure(n, 0, console_stream_write, vec![target]);
        c.set_prop(PropKey::from_str(n), Value::Obj(f), WEC);
    }
    Ok(Value::Obj(c))
}

fn console_stream_write(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let s = fmt_args(vm, a.args);
    let stream = a.slot(0);
    let w = vm.get_prop_of(&stream, &PropKey::from_str("write"))?;
    vm.call(&w, stream, &[Value::str(&format!("{}\n", s))])?;
    Ok(Value::Undefined)
}

// ---------------- console.table ----------------

fn cell(vm: &mut Vm, v: &Value) -> String {
    match v {
        Value::Obj(_) => super::util::inspect_value(vm, v, 1).unwrap_or_default(),
        other => display_value(vm, other),
    }
}

fn str_width(s: &str) -> usize {
    s.chars().count()
}

fn table(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let data = a.arg(0);
    let o = match &data {
        Value::Obj(o) => o.clone(),
        _ => return log(vm, a),
    };
    let filter: Option<Vec<String>> = match a.arg(1) {
        Value::Obj(f) => {
            let vals = crate::builtins::array::array_like_to_vec(vm, &Value::Obj(f))?;
            let mut v = Vec::new();
            for x in vals {
                v.push(vm.to_string(&x)?.to_rust_string());
            }
            Some(v)
        }
        _ => None,
    };
    // rows: (index label, value)
    let mut rows: Vec<(String, Value)> = Vec::new();
    let is_map = matches!(o.borrow().kind, ObjKind::Map(_));
    let is_set = matches!(o.borrow().kind, ObjKind::Set(_));
    if is_map || is_set {
        let entries: Vec<(Value, Value)> = match &o.borrow().kind {
            ObjKind::Map(m) | ObjKind::Set(m) => m.entries.iter().flatten().cloned().collect(),
            _ => Vec::new(),
        };
        for (i, (k, v)) in entries.into_iter().enumerate() {
            if is_map {
                let ks = display_value(vm, &k);
                rows.push((ks, v));
            } else {
                rows.push((i.to_string(), k));
            }
        }
    } else {
        let keys = vm.own_property_keys(&o)?;
        for k in keys {
            if let PropKey::Str(s) = &k {
                if let Some(d) = vm.get_own_property(&o, &k)? {
                    if d.enumerable == Some(true) {
                        let v = vm.get(&o, &k, &data)?;
                        rows.push((s.to_rust_string(), v));
                    }
                }
            }
        }
    }
    let mut columns: Vec<String> = Vec::new();
    let mut has_values = false;
    let mut row_cells: Vec<(String, Vec<(String, String)>, Option<String>)> = Vec::new();
    for (label, v) in rows {
        let mut cells = Vec::new();
        let mut value_cell = None;
        match &v {
            Value::Obj(ro) if !ro.is_callable() => {
                let keys = vm.own_property_keys(ro)?;
                for k in keys {
                    if let PropKey::Str(s) = &k {
                        if let Some(d) = vm.get_own_property(ro, &k)? {
                            if d.enumerable != Some(true) {
                                continue;
                            }
                        }
                        let name = s.to_rust_string();
                        if let Some(f) = &filter {
                            if !f.contains(&name) {
                                continue;
                            }
                        }
                        let cv = vm.get(ro, &k, &v)?;
                        let text = cell(vm, &cv);
                        if !columns.contains(&name) {
                            columns.push(name.clone());
                        }
                        cells.push((name, text));
                    }
                }
            }
            other => {
                has_values = true;
                value_cell = Some(cell(vm, other));
            }
        }
        row_cells.push((label, cells, value_cell));
    }
    if let Some(f) = &filter {
        columns = f.clone();
    }
    let mut headers = vec!["(index)".to_string()];
    headers.extend(columns.iter().cloned());
    if has_values {
        headers.push("Values".to_string());
    }
    let mut grid: Vec<Vec<String>> = Vec::new();
    for (label, cells, vc) in &row_cells {
        let mut r = vec![label.clone()];
        for c in &columns {
            r.push(cells.iter().find(|(n, _)| n == c).map(|(_, t)| t.clone()).unwrap_or_default());
        }
        if has_values {
            r.push(vc.clone().unwrap_or_default());
        }
        grid.push(r);
    }
    let widths: Vec<usize> = (0..headers.len())
        .map(|i| {
            let mut w = str_width(&headers[i]);
            for r in &grid {
                w = w.max(str_width(&r[i]));
            }
            w + 2
        })
        .collect();
    let center = |s: &str, w: usize| -> String {
        let l = str_width(s);
        let left = (w - l) / 2;
        let right = w - l - left;
        format!("{}{}{}", " ".repeat(left), s, " ".repeat(right))
    };
    let line = |l: &str, m: &str, r: &str| -> String {
        let segs: Vec<String> = widths.iter().map(|w| "─".repeat(*w)).collect();
        format!("{}{}{}", l, segs.join(m), r)
    };
    let mut out = String::new();
    out.push_str(&line("┌", "┬", "┐"));
    out.push('\n');
    let hdr: Vec<String> = headers.iter().enumerate().map(|(i, h)| center(h, widths[i])).collect();
    out.push_str(&format!("│{}│\n", hdr.join("│")));
    out.push_str(&line("├", "┼", "┤"));
    out.push('\n');
    for r in &grid {
        let cs: Vec<String> = r.iter().enumerate().map(|(i, c)| center(c, widths[i])).collect();
        out.push_str(&format!("│{}│\n", cs.join("│")));
    }
    out.push_str(&line("└", "┴", "┘"));
    out.push('\n');
    write_stdout(vm, &out);
    Ok(Value::Undefined)
}

// The runtime: host state, event loop, CLI entry.

pub mod buffer;
pub mod child_process;
pub mod fetch;
pub mod http;
pub mod jsx;
pub mod typescript;
pub mod net;
pub mod nodestream;
pub mod readline;
pub mod streams;
pub mod vmmod;
pub mod console;
pub mod encoding;
pub mod events;
pub mod fs;
pub mod node;
pub mod path;
pub mod process;
pub mod timers;
pub mod util;
pub mod web;
pub mod zlib;
pub mod cryptomod;

use crate::object::*;
use crate::value::*;
use crate::vm::{JsResult, Vm};
use std::collections::{HashMap, VecDeque};
use std::io::Write;
use std::time::Instant;

pub struct Timer {
    pub id: u64,
    pub due: f64,
    pub interval: Option<f64>,
    pub callback: Value,
    pub args: Vec<Value>,
    pub seq: u64,
}

pub enum Completion {
    /// call a JS callback with args
    Call(Value, Vec<Value>),
    /// native continuation
    Native(Box<dyn FnOnce(&mut Vm)>),
}

pub type OpResult = Box<dyn std::any::Any + Send>;
pub type OpThen = Box<dyn FnOnce(&mut Vm, OpResult)>;

pub struct Host {
    pub timers: Vec<Timer>,
    pub next_timer_id: u64,
    pub timer_seq: u64,
    pub callbacks: VecDeque<(Value, Vec<Value>)>,
    pub kept_alive: Vec<Value>,
    pub out: Vec<u8>,
    pub start: Instant,
    pub argv: Vec<String>,
    pub exec_path: String,
    pub builtin_cache: HashMap<String, Value>,
    pub cjs_cache: HashMap<String, Obj>,
    pub esm_cache: HashMap<String, std::rc::Rc<crate::modules::ModuleRecord>>,
    pub main_module: Option<Obj>,
    pub process_obj: Option<Obj>,
    pub pending_ops: usize,
    pub completions_tx: std::sync::mpsc::Sender<(u64, OpResult)>,
    pub completions_rx: std::sync::mpsc::Receiver<(u64, OpResult)>,
    pub op_thens: HashMap<u64, OpThen>,
    pub next_op_id: u64,
    pub listeners: HashMap<String, Vec<Value>>,
    pub console_counts: HashMap<String, u64>,
    pub console_timers: HashMap<String, Instant>,
    pub group_indent: usize,
    pub repl: bool,
    pub main_esm_path: String,
}

impl Host {
    pub fn new() -> Host {
        let (tx, rx) = std::sync::mpsc::channel();
        Host {
            timers: Vec::new(),
            next_timer_id: 1,
            timer_seq: 0,
            callbacks: VecDeque::new(),
            kept_alive: Vec::new(),
            out: Vec::new(),
            start: Instant::now(),
            argv: Vec::new(),
            exec_path: String::new(),
            builtin_cache: HashMap::new(),
            cjs_cache: HashMap::new(),
            esm_cache: HashMap::new(),
            main_module: None,
            process_obj: None,
            pending_ops: 0,
            completions_tx: tx,
            completions_rx: rx,
            op_thens: HashMap::new(),
            next_op_id: 1,
            listeners: HashMap::new(),
            console_counts: HashMap::new(),
            console_timers: HashMap::new(),
            group_indent: 0,
            repl: false,
            main_esm_path: String::new(),
        }
    }

    pub fn now_ms(&self) -> f64 {
        self.start.elapsed().as_secs_f64() * 1000.0
    }
}

// ---------------- output ----------------

pub fn write_stdout(vm: &mut Vm, s: &str) {
    let _ = vm;
    let out = std::io::stdout();
    let mut l = out.lock();
    let _ = l.write_all(s.as_bytes());
    let _ = l.flush();
}

pub fn write_stdout_bytes(b: &[u8]) {
    let out = std::io::stdout();
    let mut l = out.lock();
    let _ = l.write_all(b);
    let _ = l.flush();
}

pub fn write_stderr(s: &str) {
    let err = std::io::stderr();
    let mut l = err.lock();
    let _ = l.write_all(s.as_bytes());
    let _ = l.flush();
}

/// String conversion used by console.log and uncaught-rejection reports.
pub fn display_value(vm: &mut Vm, v: &Value) -> String {
    match v {
        Value::Str(s) => s.to_rust_string(),
        Value::Sym(s) => s.descriptive_string(),
        Value::Num(n) => crate::numconv::number_to_string(*n),
        Value::Obj(_) => match vm.to_string(v) {
            Ok(s) => s.to_rust_string(),
            Err(_) => "[object]".to_string(),
        },
        other => match vm.to_string(other) {
            Ok(s) => s.to_rust_string(),
            Err(_) => "[object]".to_string(),
        },
    }
}

/// "Name: message" description of a thrown value for "Uncaught ..." reports.
pub fn describe_thrown(vm: &mut Vm, e: &Value) -> String {
    match e {
        Value::Undefined | Value::Empty => "undefined".into(),
        Value::Null => "null".into(),
        Value::Num(n) => format!("Number: {}", crate::numconv::number_to_string(*n)),
        Value::Str(s) => format!("String: {}", s),
        Value::Bool(b) => format!("Boolean: {}", b),
        Value::BigInt(b) => format!("BigInt: {}", b.to_string_radix(10)),
        Value::Sym(_) => "Symbol: ".into(),
        Value::Obj(o) => {
            let name = match vm.get(o, &vm.intr.key_name.clone(), e) {
                Ok(Value::Undefined) | Err(_) => {
                    // constructor name
                    match vm.get(o, &vm.intr.key_constructor.clone(), e) {
                        Ok(Value::Obj(c)) => match vm.get(&c, &vm.intr.key_name.clone(), &Value::Obj(c.clone())) {
                            Ok(Value::Str(s)) => s.to_rust_string(),
                            _ => String::new(),
                        },
                        _ => String::new(),
                    }
                }
                Ok(v) => display_value(vm, &v),
            };
            let msg = match vm.get(o, &vm.intr.key_message.clone(), e) {
                Ok(Value::Undefined) | Err(_) => String::new(),
                Ok(v) => display_value(vm, &v),
            };
            if name.is_empty() {
                msg
            } else {
                format!("{}: {}", name, msg)
            }
        }
    }
}

pub fn report_uncaught(vm: &mut Vm, e: &Value) {
    let s = describe_thrown(vm, e);
    write_stderr(&format!("Uncaught {}\n", s));
}

pub fn report_unhandled_rejections(vm: &mut Vm) {
    let list = std::mem::take(&mut vm.unhandled);
    for p in list {
        let (handled, reason) = match &p.borrow().kind {
            ObjKind::Promise(pd) => (
                pd.is_handled,
                match &pd.state {
                    PromiseState::Rejected(r) => Some(r.clone()),
                    _ => None,
                },
            ),
            _ => (true, None),
        };
        if handled {
            continue;
        }
        if let Some(r) = reason {
            // mark as handled so it is reported once
            if let ObjKind::Promise(pd) = &mut p.borrow_mut().kind {
                pd.is_handled = true;
            }
            let s = display_value(vm, &r);
            write_stderr(&format!("Uncaught (in promise) {}\n", s));
        }
    }
}

/// Drain microtasks then report unhandled rejections (a "microtask checkpoint").
pub fn checkpoint(vm: &mut Vm) {
    vm.run_microtasks();
    report_unhandled_rejections(vm);
    vm.host.kept_alive.clear();
}

// ---------------- event loop ----------------

pub fn run_event_loop(vm: &mut Vm) {
    checkpoint(vm);
    loop {
        // 1. queued callbacks (setImmediate / nextTick), snapshot
        let n = vm.host.callbacks.len();
        for _ in 0..n {
            if let Some((f, args)) = vm.host.callbacks.pop_front() {
                if let Err(e) = vm.call(&f, Value::Undefined, &args) {
                    report_uncaught(vm, &e);
                }
                checkpoint(vm);
            }
        }
        // 2. completions from background work
        loop {
            match vm.host.completions_rx.try_recv() {
                Ok((id, payload)) => {
                    finish_op(vm, id, payload);
                    checkpoint(vm);
                }
                Err(_) => break,
            }
        }
        // 3. due timers
        let now = vm.host.now_ms();
        let mut due: Vec<(f64, u64, u64)> = vm.host.timers.iter().filter(|t| t.due <= now).map(|t| (t.due, t.seq, t.id)).collect();
        due.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap().then(a.1.cmp(&b.1)));
        for (_, _, id) in due {
            let pos = match vm.host.timers.iter().position(|t| t.id == id) {
                Some(p) => p,
                None => continue,
            };
            let (cb, args, interval) = {
                let t = &vm.host.timers[pos];
                (t.callback.clone(), t.args.clone(), t.interval)
            };
            match interval {
                Some(iv) => {
                    let now2 = vm.host.now_ms();
                    vm.host.timer_seq += 1;
                    let seq = vm.host.timer_seq;
                    let t = &mut vm.host.timers[pos];
                    t.due = now2 + iv;
                    t.seq = seq;
                }
                None => {
                    vm.host.timers.remove(pos);
                }
            }
            if let Err(e) = vm.call(&cb, Value::Undefined, &args) {
                report_uncaught(vm, &e);
            }
            checkpoint(vm);
        }
        // anything left?
        if !vm.host.callbacks.is_empty() {
            continue;
        }
        if vm.host.timers.is_empty() && vm.host.pending_ops == 0 {
            break;
        }
        // wait for the next timer or a completion
        let next_due = vm.host.timers.iter().map(|t| t.due).fold(f64::INFINITY, f64::min);
        let now = vm.host.now_ms();
        if vm.host.pending_ops > 0 {
            let wait = if next_due.is_finite() { (next_due - now).max(0.0) } else { 3600_000.0 };
            match vm.host.completions_rx.recv_timeout(std::time::Duration::from_micros((wait * 1000.0) as u64)) {
                Ok((id, payload)) => {
                    finish_op(vm, id, payload);
                    checkpoint(vm);
                }
                Err(_) => {}
            }
        } else if next_due.is_finite() && next_due > now {
            std::thread::sleep(std::time::Duration::from_micros(((next_due - now) * 1000.0) as u64));
        }
    }
}

pub fn run_completion(vm: &mut Vm, c: Completion) {
    match c {
        Completion::Call(f, args) => {
            if let Err(e) = vm.call(&f, Value::Undefined, &args) {
                report_uncaught(vm, &e);
            }
        }
        Completion::Native(f) => f(vm),
    }
}

fn finish_op(vm: &mut Vm, id: u64, payload: OpResult) {
    vm.host.pending_ops = vm.host.pending_ops.saturating_sub(1);
    if let Some(then) = vm.host.op_thens.remove(&id) {
        then(vm, payload);
    }
}

/// Run `work` on a background thread; `then` runs on the loop thread with its result.
pub fn spawn_op<T: Send + 'static>(vm: &mut Vm, work: impl FnOnce() -> T + Send + 'static, then: impl FnOnce(&mut Vm, T) + 'static) {
    let id = vm.host.next_op_id;
    vm.host.next_op_id += 1;
    vm.host.pending_ops += 1;
    vm.host.op_thens.insert(
        id,
        Box::new(move |vm: &mut Vm, payload: OpResult| {
            if let Ok(v) = payload.downcast::<T>() {
                then(vm, *v);
            }
        }),
    );
    let tx = vm.host.completions_tx.clone();
    std::thread::spawn(move || {
        let r = work();
        let _ = tx.send((id, Box::new(r) as OpResult));
    });
}

