169	    while let Some(c) = cur {
170	        if let Some(Value::Obj(ctor)) = c.get_own_data(&vm.intr.key_constructor.clone()) {
171	            if let Some(Value::Str(n)) = ctor.get_own_data(&vm.intr.key_name.clone()) {
172	                return Some(n.to_rust_string());
173	            }
174	        }
175	        cur = c.borrow().proto.clone();
176	    }
177	    None
178	}
