180	fn is_ident_key(s: &str) -> bool {
181	    let mut chars = s.chars();
182	    match chars.next() {
183	        Some(c) if c == '_' || c == '$' || c.is_alphabetic() => {}
184	        _ => return false,
185	    }
186	    chars.all(|c| c == '_' || c == '$' || c.is_alphanumeric())
187	}
