189	fn quote_str(s: &str) -> String {
190	    let mut out = String::with_capacity(s.len() + 2);
191	    out.push('\'');
192	    for c in s.chars() {
193	        match c {
194	            '\'' => out.push_str("\\'"),
195	            '\\' => out.push_str("\\\\"),
196	            _ => out.push(c),
197	        }
198	    }
199	    out.push('\'');
200	    out
201	}
