208	pub fn inspect_with_options(vm: &mut Vm, v: &Value, opts: &Value) -> JsResult<String> {
209	    let mut depth = 2;
210	    if let Value::Obj(o) = opts {
211	        let d = vm.get_str(o, "depth")?;
212	        match d {
213	            Value::Num(n) => depth = if n.is_infinite() { 1000 } else { n as i32 },
214	            Value::Null => depth = 0,
215	            _ => {}
216	        }
217	    }
218	    let mut seen = Vec::new();
219	    fmt_value(vm, v, 0, depth, &mut seen, true)
220	}
