222	fn fmt_value(vm: &mut Vm, v: &Value, level: i32, max_depth: i32, seen: &mut Vec<Obj>, top: bool) -> JsResult<String> {
223	    match v {
224	        Value::Str(s) => Ok(if top { s.to_rust_string() } else { quote_str(&s.to_rust_string()) }),
225	        Value::Num(n) => Ok(crate::numconv::number_to_string(*n)),
226	        Value::BigInt(b) => Ok(format!("{}n", b.to_string_radix(10))),
227	        Value::Bool(b) => Ok(b.to_string()),
228	        Value::Undefined | Value::Empty => Ok("undefined".into()),
229	        Value::Null => Ok("null".into()),
230	        Value::Sym(s) => Ok(s.descriptive_string()),
231	        Value::Obj(o) => fmt_object(vm, o, level, max_depth, seen),
232	    }
233	}
234	
235	fn fmt_object(vm: &mut Vm, o: &Obj, level: i32, max_depth: i32, seen: &mut Vec<Obj>) -> JsResult<String> {
236	    if seen.iter().any(|s| s.ptr_eq(o)) {
237	        return Ok("[Circular *1]".into());
238	    }
239	    // custom inspect
240	    let custom = vm.symbol_for("nodejs.util.inspect.custom");
241	    let ov = Value::Obj(o.clone());
242	    if let Ok(f) = vm.get(o, &PropKey::Sym(custom), &ov) {
243	        if f.is_callable() {
244	            let opts = vm.obj_from(vec![("depth", Value::Num((max_depth - level) as f64))]);
245	            let r = vm.call(&f, ov.clone(), &[Value::Num((max_depth - level) as f64), Value::Obj(opts)])?;
246	            return match &r {
247	                Value::Str(s) => Ok(s.to_rust_string()),
248	                other => fmt_value(vm, other, level, max_depth, seen, false),
249	            };
250	        }
251	    }
252	    enum K {
253	        Func,
254	        Error,
255	        Date(f64),
256	        RegExp,
257	        Map,
258	        Set,
259	        Array,
260	        Named(&'static str),
261	        Buffer,
262	        Proxy(Option<Obj>),
263	        Plain,
264	    }
265	    let k = {
266	        let b = o.borrow();
267	        match &b.kind {
268	            ObjKind::Closure(_) | ObjKind::Native(_) | ObjKind::Bound(_) => K::Func,
269	            ObjKind::Proxy(p) => {
270	                if p.callable {
271	                    K::Func
272	                } else {
273	                    K::Proxy(p.target.clone())
274	                }
275	            }
276	            ObjKind::Error => K::Error,
277	            ObjKind::Date(t) => K::Date(*t),
278	            ObjKind::RegExp(_) => K::RegExp,
279	            ObjKind::Map(_) => K::Map,
280	            ObjKind::Set(_) => K::Set,
281	            ObjKind::Array(_) => K::Array,
282	            ObjKind::Promise(_) => K::Named("Promise"),
283	            ObjKind::WeakMap(_) => K::Named("WeakMap"),
284	            ObjKind::WeakSet(_) => K::Named("WeakSet"),
285	            ObjKind::WeakRef(_) => K::Named("WeakRef"),
286	            ObjKind::TypedArray(t) if t.kind == TAKind::Uint8 && b.proto.as_ref().map_or(false, |p| crate::runtime::buffer::is_buffer_proto(vm, p)) => K::Buffer,
287	            _ => K::Plain,
288	        }
289	    };
290	    match k {
291	        K::Func => {
292	            let name = match vm.get(o, &vm.intr.key_name.clone(), &Value::Obj(o.clone())) {
293	                Ok(Value::Str(s)) if !s.is_empty() => Some(s.to_rust_string()),
294	                _ => None,
295	            };
296	            Ok(match name {
297	                Some(n) => format!("[Function: {}]", n),
298	                None => "[Function (anonymous)]".into(),
299	            })
300	        }
301	        K::Error => {
302	            let st = vm.get(o, &PropKey::from_str("stack"), &Value::Obj(o.clone()))?;
303	            match st {
304	                Value::Str(s) => Ok(s.to_rust_string()),
305	                _ => Ok(crate::runtime::display_value(vm, &Value::Obj(o.clone()))),
306	            }
307	        }
308	        K::Date(t) => Ok(crate::datetime::to_iso_string(t).unwrap_or_else(|| "Invalid Date".into())),
309	        K::RegExp => Ok(crate::runtime::display_value(vm, &Value::Obj(o.clone()))),
310	        K::Named(n) => Ok(format!("{} {{}}", n)),
311	        K::Buffer => {
312	            let bytes = crate::builtins::typedarray::ta_bytes(o);
313	            let shown: Vec<String> = bytes.iter().take(50).map(|b| format!("{:02x}", b)).collect();
314	            let more = if bytes.len() > 50 { format!(" ... {} more bytes", bytes.len() - 50) } else { String::new() };
315	            Ok(format!("<Buffer{}{}{}>", if shown.is_empty() { "" } else { " " }, shown.join(" "), more))
316	        }
317	        K::Proxy(t) => match t {
318	            Some(t) => fmt_object(vm, &t, level, max_depth, seen),
319	            None => Ok("{}".into()),
320	        },
321	        K::Map | K::Set => {
322	            if level > max_depth {
323	                return Ok(if matches!(k, K::Map) { "[Map]".into() } else { "[Set]".into() });
324	            }
325	            let entries: Vec<(Value, Value)> = match &o.borrow().kind {
326	                ObjKind::Map(m) | ObjKind::Set(m) => m.entries.iter().flatten().cloned().collect(),
327	                _ => Vec::new(),
328	            };
329	            seen.push(o.clone());
330	            let mut parts = Vec::new();
331	            for (key, val) in &entries {
332	                if matches!(k, K::Map) {
333	                    let ks = fmt_value(vm, key, level + 1, max_depth, seen, false)?;
334	                    let vs = fmt_value(vm, val, level + 1, max_depth, seen, false)?;
335	                    parts.push(format!("{} => {}", ks, vs));
336	                } else {
337	                    parts.push(fmt_value(vm, key, level + 1, max_depth, seen, false)?);
338	                }
339	            }
340	            seen.pop();
341	            let name = if matches!(k, K::Map) { "Map" } else { "Set" };
342	            Ok(format!("{}({}) {{ {} }}", name, entries.len(), parts.join(", ")))
343	        }
344	        K::Array => {
345	            if level > max_depth {
346	                return Ok("[Array]".into());
347	            }
348	            let len = vm.length_of(o)?;
349	            seen.push(o.clone());
350	            let mut parts = Vec::new();
351	            for i in 0..len {
352	                let key = PropKey::from_index(i as u32);
353	                if vm.ordinary_get_own(o, &key).is_none() {
354	                    parts.push(String::new());
355	                    continue;
356	                }
357	                let val = vm.get(o, &key, &Value::Obj(o.clone()))?;
358	                parts.push(fmt_value(vm, &val, level + 1, max_depth, seen, false)?);
359	            }
360	            seen.pop();
361	            if parts.is_empty() {
362	                return Ok("[]".into());
363	            }
364	            Ok(format!("[ {} ]", parts.join(", ")))
365	        }
366	        K::Plain => {
367	            let prefix = {
368	                let proto = o.borrow().proto.clone();
369	                match proto {
370	                    None => String::new(),
371	                    Some(_) => match constructor_name(vm, o) {
372	                        Some(n) if n != "Object" && !n.is_empty() => format!("{} ", n),
373	                        _ => String::new(),
374	                    },
375	                }
376	            };
377	            if level > max_depth {
378	                return Ok("[Object]".into());
379	            }
380	            let keys = vm.own_property_keys(o)?;
381	            seen.push(o.clone());
382	            let mut parts = Vec::new();
383	            for key in keys {
384	                let s = match &key {
385	                    PropKey::Str(s) => s.to_rust_string(),
386	                    PropKey::Sym(_) => continue,
387	                };
388	                match vm.get_own_property(o, &key)? {
389	                    Some(d) if d.enumerable == Some(true) => {}
390	                    _ => continue,
391	                }
392	                let val = vm.get(o, &key, &Value::Obj(o.clone()))?;
393	                let vs = fmt_value(vm, &val, level + 1, max_depth, seen, false)?;
394	                let ks = if is_ident_key(&s) { s } else { quote_str(&s) };
395	                parts.push(format!("{}: {}", ks, vs));
396	            }
397	            seen.pop();
398	            if parts.is_empty() {
399	                return Ok(format!("{}{{}}", prefix));
400	            }
401	            Ok(format!("{}{{ {} }}", prefix, parts.join(", ")))
402	        }
403	    }
404	}
