411	pub fn format_args(vm: &mut Vm, args: &[Value]) -> JsResult<String> {
412	    if args.is_empty() {
413	        return Ok(String::new());
414	    }
415	    let mut out = String::new();
416	    let mut rest_start = 1;
417	    if let Value::Str(fs) = &args[0] {
418	        let f = fs.to_rust_string();
419	        let chars: Vec<char> = f.chars().collect();
420	        let mut ai = 1;
421	        let mut i = 0;
422	        while i < chars.len() {
423	            let c = chars[i];
424	            if c == '%' && i + 1 < chars.len() {
425	                let n = chars[i + 1];
426	                match n {
427	                    '%' => {
428	                        out.push('%');
429	                        i += 2;
430	                        continue;
431	                    }
432	                    's' | 'd' | 'i' | 'f' | 'j' | 'o' | 'O' | 'c' => {
433	                        if ai >= args.len() {
434	                            out.push(c);
435	                            out.push(n);
436	                            i += 2;
437	                            continue;
438	                        }
439	                        let v = args[ai].clone();
440	                        ai += 1;
441	                        let piece = match n {
442	                            's' => match &v {
443	                                Value::Str(s) => s.to_rust_string(),
444	                                Value::Obj(_) => inspect_value(vm, &v, 1)?,
445	                                other => crate::runtime::display_value(vm, other),
446	                            },
447	                            'd' => match &v {
448	                                Value::Obj(_) => "NaN".into(),
449	                                Value::BigInt(b) => format!("{}n", b.to_string_radix(10)),
450	                                other => crate::numconv::number_to_string(vm.to_number(other).unwrap_or(f64::NAN)),
451	                            },
452	                            'i' => {
453	                                let s = vm.to_string(&v).unwrap_or_else(|_| JsStr::from_str("NaN"));
454	                                crate::numconv::number_to_string(crate::numconv::parse_int(s.units(), 10))
455	                            }
456	                            'f' => {
457	                                let s = vm.to_string(&v).unwrap_or_else(|_| JsStr::from_str("NaN"));
458	                                crate::numconv::number_to_string(crate::numconv::parse_float(s.units()))
459	                            }
460	                            'j' => match crate::builtins::json::json_stringify(vm, &v, &Value::Undefined, &Value::Undefined) {
461	                                Ok(Some(s)) => s.to_rust_string(),
462	                                Ok(None) => "undefined".into(),
463	                                Err(_) => "[Circular]".into(),
464	                            },
465	                            'c' => String::new(),
466	                            _ => inspect_value(vm, &v, 2)?,
467	                        };
468	                        out.push_str(&piece);
469	                        i += 2;
470	                        continue;
471	                    }
472	                    _ => {}
473	                }
474	            }
475	            out.push(c);
476	            i += 1;
477	        }
478	        rest_start = ai;
479	    } else {
480	        rest_start = 0;
481	    }
482	    for (j, v) in args[rest_start..].iter().enumerate() {
483	        if j > 0 || rest_start > 0 {
484	            out.push(' ');
485	        }
486	        let s = match v {
487	            Value::Str(s) => s.to_rust_string(),
488	            other => inspect_value(vm, other, 2)?,
489	        };
490	        out.push_str(&s);
491	    }
492	    Ok(out)
493	}
