504	fn inherits(vm: &mut Vm, a: &Args) -> JsResult<Value> {
505	    let ctor = a.arg(0);
506	    let sup = a.arg(1);
507	    let (c, s) = match (&ctor, &sup) {
508	        (Value::Obj(c), Value::Obj(s)) => (c.clone(), s.clone()),
509	        _ => return vm.throw_type("The \"ctor\" and \"superCtor\" arguments must be functions"),
510	    };
511	    let sp = vm.get_str(&s, "prototype")?;
