527	fn deprecated_call(vm: &mut Vm, a: &Args) -> JsResult<Value> {
528	    if !a.slot(3).truthy() {
529	        if let ObjKind::Native(n) = &mut a.callee.borrow_mut().kind {
530	            n.slots[3] = Value::Bool(true);
531	        }
532	        let msg = crate::runtime::display_value(vm, &a.slot(1));
533	        let code = a.slot(2);
534	        let line = if code.is_undefined() {
535	            format!("(node:{}) DeprecationWarning: {}\n", std::process::id(), msg)
536	        } else {
537	            format!("(node:{}) [{}] DeprecationWarning: {}\n", std::process::id(), crate::runtime::display_value(vm, &code), msg)
538	        };
539	        crate::runtime::write_stderr(&line);
540	    }
541	    vm.call(&a.slot(0), a.this.clone(), a.args)
542	}
