544	fn promisify(vm: &mut Vm, a: &Args) -> JsResult<Value> {
545	    let f = a.arg(0);
546	    if !f.is_callable() {
547	        let d = describe_received(vm, &f);
548	        return vm.throw_type(format!("The \"original\" argument must be of type function. Received {}", d));
549	    }
550	    let custom = vm.symbol_for("nodejs.util.promisify.custom");
551	    let c = vm.get_prop_of(&f, &PropKey::Sym(custom))?;
552	    if c.is_callable() {
553	        return Ok(c);
554	    }
555	    Ok(Value::Obj(vm.native_closure("promisified", 0, promisified_call, vec![f])))
556	}
