558	fn promisified_call(vm: &mut Vm, a: &Args) -> JsResult<Value> {
559	    let cap = vm.new_promise_capability_intrinsic();
560	    let cb = vm.native_closure("", 2, promisify_cb, vec![cap.resolve.clone(), cap.reject.clone()]);
561	    let mut args = a.args.to_vec();
562	    args.push(Value::Obj(cb));
563	    if let Err(e) = vm.call(&a.slot(0), a.this.clone(), &args) {
564	        vm.call(&cap.reject, Value::Undefined, &[e])?;
565	    }
566	    Ok(cap.promise)
567	}
