569	fn promisify_cb(vm: &mut Vm, a: &Args) -> JsResult<Value> {
570	    let err = a.arg(0);
571	    if !err.is_nullish() {
572	        vm.call(&a.slot(1), Value::Undefined, &[err])?;
573	    } else {
574	        vm.call(&a.slot(0), Value::Undefined, &[a.arg(1)])?;
575	    }
576	    Ok(Value::Undefined)
577	}
