579	fn callbackify(vm: &mut Vm, a: &Args) -> JsResult<Value> {
580	    let f = a.arg(0);
581	    if !f.is_callable() {
582	        return vm.throw_type("The \"original\" argument must be of type function");
583	    }
584	    Ok(Value::Obj(vm.native_closure("callbackified", 0, callbackified_call, vec![f])))
585	}
