587	fn callbackified_call(vm: &mut Vm, a: &Args) -> JsResult<Value> {
588	    let mut args = a.args.to_vec();
589	    let cb = args.pop().unwrap_or(Value::Undefined);
590	    if !cb.is_callable() {
591	        return vm.throw_type("The last argument must be of type function");
592	    }
593	    let p = vm.call(&a.slot(0), a.this.clone(), &args)?;
594	    let p = crate::builtins::promise::promise_resolve_intrinsic(vm, p)?;
595	    let on_ok = vm.native_closure("", 1, |vm, a| {
596	        let cb = a.slot(0);
597	        vm.host.callbacks.push_back((cb, vec![Value::Null, a.arg(0)]));
598	        Ok(Value::Undefined)
599	    }, vec![cb.clone()]);
600	    let on_err = vm.native_closure("", 1, |vm, a| {
601	        let cb = a.slot(0);
602	        vm.host.callbacks.push_back((cb, vec![a.arg(0)]));
603	        Ok(Value::Undefined)
604	    }, vec![cb]);
605	    crate::builtins::promise::promise_then(vm, &p, Value::Obj(on_ok), Value::Obj(on_err))?;
606	    Ok(Value::Undefined)
607	}
