609	fn strip_vt(vm: &mut Vm, a: &Args) -> JsResult<Value> {
610	    let s = vm.to_string(&a.arg(0))?.to_rust_string();
611	    let mut out = String::new();
612	    let mut chars = s.chars().peekable();
613	    while let Some(c) = chars.next() {
614	        if c == '\u{1b}' {
615	            if chars.peek() == Some(&'[') {
616	                chars.next();
617	                while let Some(&n) = chars.peek() {
618	                    chars.next();
619	                    if n.is_ascii_alphabetic() {
620	                        break;
621	                    }
622	                }
623	            }
624	            continue;
625	        }
626	        out.push(c);
627	    }
628	    Ok(Value::str(&out))
629	}
