651	fn parse_args(vm: &mut Vm, a: &Args) -> JsResult<Value> {
652	    let cfg = a.arg(0);
653	    let args_v = match &cfg {
654	        Value::Obj(c) => vm.get_str(c, "args")?,
655	        _ => Value::Undefined,
656	    };
657	    let args: Vec<String> = if args_v.is_undefined() {
658	        vm.host.argv.iter().skip(2).cloned().collect()
659	    } else {
660	        let v = crate::builtins::array::array_like_to_vec(vm, &args_v)?;
661	        let mut out = Vec::new();
662	        for x in v {
663	            out.push(vm.to_string(&x)?.to_rust_string());
664	        }
665	        out
666	    };
667	    let options = match &cfg {
668	        Value::Obj(c) => vm.get_str(c, "options")?,
669	        _ => Value::Undefined,
670	    };
671	    let allow_positionals = match &cfg {
672	        Value::Obj(c) => vm.get_str(c, "allowPositionals")?.truthy(),
673	        _ => false,
674	    };
675	    let values = Obj::new(None, ObjKind::Ordinary);
676	    let mut positionals = Vec::new();
677	    // option specs
678	    let mut specs: Vec<(String, String, Option<String>, bool)> = Vec::new();
679	    if let Value::Obj(oo) = &options {
680	        let keys = vm.enumerable_own_keys(oo)?;
681	        for k in keys {
682	            let spec = vm.get(oo, &PropKey::Str(k.clone()), &options)?;
683	            let (ty, short, multiple, default) = match &spec {
684	                Value::Obj(so) => {
685	                    let t = vm.get_str(so, "type")?;
686	                    let s = vm.get_str(so, "short")?;
687	                    let m = vm.get_str(so, "multiple")?.truthy();
688	                    let d = vm.get_str(so, "default")?;
689	                    (
690	                        if t.is_undefined() { "boolean".to_string() } else { vm.to_string(&t)?.to_rust_string() },
691	                        if s.is_undefined() { None } else { Some(vm.to_string(&s)?.to_rust_string()) },
692	                        m,
693	                        d,
694	                    )
695	                }
696	                _ => ("boolean".into(), None, false, Value::Undefined),
697	            };
698	            if !default.is_undefined() {
699	                values.set_prop(PropKey::Str(k.clone()), default, WEC);
700	            }
701	            specs.push((k.to_rust_string(), ty, short, multiple));
702	        }
703	    }
704	    let mut i = 0;
705	    while i < args.len() {
706	        let arg = &args[i];
707	        if arg == "--" {
708	            for p in &args[i + 1..] {
709	                positionals.push(Value::str(p));
710	            }
711	            break;
712	        }
713	        let (name, inline): (Option<String>, Option<String>) = if let Some(long) = arg.strip_prefix("--") {
714	            match long.find('=') {
715	                Some(p) => (Some(long[..p].to_string()), Some(long[p + 1..].to_string())),
716	                None => (Some(long.to_string()), None),
717	            }
718	        } else if arg.starts_with('-') && arg.len() > 1 {
719	            let s = &arg[1..2];
720	            let found = specs.iter().find(|sp| sp.2.as_deref() == Some(s)).map(|sp| sp.0.clone());
721	            (Some(found.unwrap_or_else(|| s.to_string())), if arg.len() > 2 { Some(arg[2..].to_string()) } else { None })
722	        } else {
723	            if !allow_positionals {
724	                return vm.throw_type(format!("Unexpected argument '{}'. This command does not take positional arguments", arg));
725	            }
726	            positionals.push(Value::str(arg));
727	            i += 1;
728	            continue;
729	        };
730	        let name = name.unwrap();
731	        let spec = specs.iter().find(|s| s.0 == name).cloned();
732	        match spec {
733	            None => return vm.throw_type(format!("Unknown option '--{}'", name)),
734	            Some((n, ty, _, multiple)) => {
735	                let val = if ty == "string" {
736	                    match inline {
737	                        Some(v) => Value::str(&v),
738	                        None => {
739	                            i += 1;
740	                            match args.get(i) {
741	                                Some(v) => Value::str(v),
742	                                None => return vm.throw_type(format!("Option '--{} <value>' argument missing", n)),
743	                            }
744	                        }
745	                    }
746	                } else {
747	                    Value::Bool(true)
748	                };
749	                if multiple {
750	                    let k = PropKey::from_str(&n);
751	                    let existing = values.get_own_data(&k);
752	                    match existing {
753	                        Some(Value::Obj(arr)) if arr.is_array() => crate::vm::array_push_raw(&arr, val),
754	                        _ => {
755	                            let arr = vm.new_array(vec![val]);
756	                            values.set_prop(k, Value::Obj(arr), WEC);
757	                        }
758	                    }
759	                } else {
760	                    values.set_prop(PropKey::from_str(&n), val, WEC);
761	                }
762	            }
763	        }
764	        i += 1;
765	    }
766	    let r = vm.new_object();
767	    r.set_str("values", Value::Obj(values), WEC);
768	    let pa = vm.new_array(positionals);
769	    r.set_str("positionals", Value::Obj(pa), WEC);
770	    Ok(Value::Obj(r))
771	}
