773	// ---------------- deep equality ----------------
774	
775	pub fn deep_equal(vm: &mut Vm, a: &Value, b: &Value, strict: bool) -> JsResult<bool> {
776	    let mut memo = Vec::new();
777	    deep_eq_inner(vm, a, b, strict, &mut memo)
778	}
779	
780	fn deep_eq_inner(vm: &mut Vm, a: &Value, b: &Value, strict: bool, memo: &mut Vec<(Obj, Obj)>) -> JsResult<bool> {
781	    match (a, b) {
782	        (Value::Obj(x), Value::Obj(y)) => {
783	            if x.ptr_eq(y) {
784	                return Ok(true);
785	            }
786	            if memo.iter().any(|(p, q)| p.ptr_eq(x) && q.ptr_eq(y)) {
787	                return Ok(true);
788	            }
789	            if strict {
790	                let px = vm.get_prototype_of(x)?;
791	                let py = vm.get_prototype_of(y)?;
792	                let same = match (&px, &py) {
793	                    (Some(p), Some(q)) => p.ptr_eq(q),
794	                    (None, None) => true,
795	                    _ => false,
796	                };
797	                if !same {
798	                    return Ok(false);
799	                }
800	            }
801	            let xa = x.is_array();
802	            if xa != y.is_array() {
803	                return Ok(false);
804	            }
805	            enum Spec {
806	                Date(f64, f64),
807	                Re(String, String),
808	                Map,
809	                Set,
810	                Boxed,
811	                Ta(Vec<u8>, Vec<u8>),
812	                Err,
813	                None,
814	            }
815	            let spec = {
816	                let bx = x.borrow();
817	                let by = y.borrow();
818	                match (&bx.kind, &by.kind) {
819	                    (ObjKind::Date(p), ObjKind::Date(q)) => Spec::Date(*p, *q),
820	                    (ObjKind::RegExp(p), ObjKind::RegExp(q)) => Spec::Re(format!("{}/{}", p.source, p.flags), format!("{}/{}", q.source, q.flags)),
821	                    (ObjKind::Map(_), ObjKind::Map(_)) => Spec::Map,
822	                    (ObjKind::Set(_), ObjKind::Set(_)) => Spec::Set,
823	                    (ObjKind::Number(_), ObjKind::Number(_)) | (ObjKind::String(_), ObjKind::String(_)) | (ObjKind::Boolean(_), ObjKind::Boolean(_)) => Spec::Boxed,
824	                    (ObjKind::TypedArray(_), ObjKind::TypedArray(_)) => {
825	                        drop(bx);
826	                        drop(by);
827	                        Spec::Ta(crate::builtins::typedarray::ta_bytes(x), crate::builtins::typedarray::ta_bytes(y))
828	                    }
829	                    (ObjKind::Error, ObjKind::Error) => Spec::Err,
830	                    (ObjKind::Date(_), _) | (_, ObjKind::Date(_)) | (ObjKind::RegExp(_), _) | (_, ObjKind::RegExp(_)) | (ObjKind::Map(_), _) | (_, ObjKind::Map(_)) | (ObjKind::Set(_), _) | (_, ObjKind::Set(_)) => {
831	                        return Ok(false)
832	                    }
833	                    _ => Spec::None,
834	                }
835	            };
836	            match spec {
837	                Spec::Date(p, q) => {
838	                    if !(p == q || (p.is_nan() && q.is_nan())) {
839	                        return Ok(false);
840	                    }
841	                }
842	                Spec::Re(p, q) => {
843	                    if p != q {
844	                        return Ok(false);
845	                    }
846	                }
847	                Spec::Boxed => {
848	                    let p = vm.to_primitive(a, crate::ops::Hint::Default)?;
849	                    let q = vm.to_primitive(b, crate::ops::Hint::Default)?;
850	                    if !Value::same_value(&p, &q) {
851	                        return Ok(false);
852	                    }
853	                }
854	                Spec::Ta(p, q) => {
855	                    if p != q {
856	                        return Ok(false);
857	                    }
858	                }
859	                Spec::Err => {
860	                    let mx = vm.get_str(x, "message")?;
861	                    let my = vm.get_str(y, "message")?;
862	                    let nx = vm.get_str(x, "name")?;
863	                    let ny = vm.get_str(y, "name")?;
864	                    if !Value::strict_eq(&mx, &my) || !Value::strict_eq(&nx, &ny) {
865	                        return Ok(false);
866	                    }
867	                }
868	                Spec::Map => {
869	                    let ex: Vec<(Value, Value)> = match &x.borrow().kind {
870	                        ObjKind::Map(m) => m.entries.iter().flatten().cloned().collect(),
871	                        _ => Vec::new(),
872	                    };
873	                    let ey: Vec<(Value, Value)> = match &y.borrow().kind {
874	                        ObjKind::Map(m) => m.entries.iter().flatten().cloned().collect(),
875	                        _ => Vec::new(),
876	                    };
877	                    if ex.len() != ey.len() {
878	                        return Ok(false);
879	                    }
880	                    memo.push((x.clone(), y.clone()));
881	                    for (k, v) in &ex {
882	                        let other = match &y.borrow().kind {
883	                            ObjKind::Map(m) => m.get(k).cloned(),
884	                            _ => None,
885	                        };
886	                        let found = match other {
887	                            Some(ov) => deep_eq_inner(vm, v, &ov, strict, memo)?,
888	                            None => {
889	                                let mut f = false;
890	                                for (k2, v2) in &ey {
891	                                    if deep_eq_inner(vm, k, k2, strict, memo)? && deep_eq_inner(vm, v, v2, strict, memo)? {
892	                                        f = true;
893	                                        break;
894	                                    }
895	                                }
896	                                f
897	                            }
898	                        };
899	                        if !found {
900	                            memo.pop();
901	                            return Ok(false);
902	                        }
903	                    }
904	                    memo.pop();
905	                }
906	                Spec::Set => {
907	                    let ex: Vec<Value> = match &x.borrow().kind {
908	                        ObjKind::Set(m) => m.entries.iter().flatten().map(|(k, _)| k.clone()).collect(),
909	                        _ => Vec::new(),
910	                    };
911	                    let ey: Vec<Value> = match &y.borrow().kind {
912	                        ObjKind::Set(m) => m.entries.iter().flatten().map(|(k, _)| k.clone()).collect(),
913	                        _ => Vec::new(),
914	                    };
915	                    if ex.len() != ey.len() {
916	                        return Ok(false);
917	                    }
918	                    for k in &ex {
919	                        let has = match &y.borrow().kind {
920	                            ObjKind::Set(m) => m.has(k),
921	                            _ => false,
922	                        };
923	                        if !has {
924	                            let mut f = false;
925	                            for k2 in &ey {
926	                                if k2.is_object() && deep_eq_inner(vm, k, k2, strict, memo)? {
927	                                    f = true;
928	                                    break;
929	                                }
930	                            }
931	                            if !f {
932	                                return Ok(false);
933	                            }
934	                        }
935	                    }
936	                }
937	                Spec::None => {}
938	            }
939	            let kx = own_enum_keys(vm, x)?;
940	            let ky = own_enum_keys(vm, y)?;
941	            if kx.len() != ky.len() {
942	                return Ok(false);
943	            }
944	            memo.push((x.clone(), y.clone()));
945	            for k in &kx {
946	                if !ky.contains(k) {
947	                    memo.pop();
948	                    return Ok(false);
949	                }
950	                let vx = vm.get(x, k, a)?;
951	                let vy = vm.get(y, k, b)?;
952	                if !deep_eq_inner(vm, &vx, &vy, strict, memo)? {
953	                    memo.pop();
954	                    return Ok(false);
955	                }
956	            }
957	            memo.pop();
958	            Ok(true)
959	        }
960	        (Value::Obj(_), _) | (_, Value::Obj(_)) => {
961	            if strict {
962	                Ok(false)
963	            } else {
964	                Ok(vm.loose_eq(a, b)?)
965	            }
966	        }
967	        _ => {
968	            if strict {
969	                Ok(Value::same_value(a, b))
970	            } else {
971	                Ok(Value::strict_eq(a, b) || vm.loose_eq(a, b)? || (matches!((a, b), (Value::Num(x), Value::Num(y)) if x.is_nan() && y.is_nan())))
972	            }
973	        }
974	    }
975	}
976	
977	fn own_enum_keys(vm: &mut Vm, o: &Obj) -> JsResult<Vec<PropKey>> {
978	    let keys = vm.own_property_keys(o)?;
979	    let mut out = Vec::new();
980	    for k in keys {
981	        if k.is_private() {
982	            continue;
983	        }
984	        if let Some(d) = vm.get_own_property(o, &k)? {
985	            if d.enumerable == Some(true) {
986	                out.push(k);
987	            }
988	        }
989	    }
990	    Ok(out)
991	}
