994	
995	pub fn create_assert_module(vm: &mut Vm) -> Value {
996	    let a = vm.native_fn("ok", 2, assert_ok);
997	    let fns: &[(&str, u32, NativeFn)] = &[
998	        ("ok", 2, assert_ok),
999	        ("equal", 3, |vm, a| assert_cmp(vm, a, "==")),
1000	        ("notEqual", 3, |vm, a| assert_cmp(vm, a, "!=")),
1001	        ("strictEqual", 3, |vm, a| assert_cmp(vm, a, "===")),
1002	        ("notStrictEqual", 3, |vm, a| assert_cmp(vm, a, "!==")),
1003	        ("deepEqual", 3, |vm, a| assert_cmp(vm, a, "deepEqual")),
1004	        ("deepStrictEqual", 3, |vm, a| assert_cmp(vm, a, "deepStrictEqual")),
1005	        ("notDeepEqual", 3, |vm, a| assert_cmp(vm, a, "notDeepEqual")),
1006	        ("notDeepStrictEqual", 3, |vm, a| assert_cmp(vm, a, "notDeepStrictEqual")),
1007	        ("throws", 3, assert_throws),
1008	        ("doesNotThrow", 3, assert_does_not_throw),
1009	        ("rejects", 3, assert_rejects),
1010	        ("doesNotReject", 3, |vm, _a| Ok(vm.new_promise_capability_intrinsic().promise)),
1011	        ("fail", 1, assert_fail),
1012	        ("match", 3, |vm, a| assert_match(vm, a, true)),
1013	        ("doesNotMatch", 3, |vm, a| assert_match(vm, a, false)),
1014	        ("ifError", 1, |_vm, a| if a.arg(0).is_nullish() { Ok(Value::Undefined) } else { Err(a.arg(0)) }),
1015	    ];
1016	    for (n, l, f) in fns {
1017	        vm.def_method(&a, n, *l, *f);
1018	    }
1019	    a.set_prop(PropKey::from_str("strict"), Value::Obj(a.clone()), WEC);
1020	    let aep = Obj::new(Some(vm.intr.error_proto.clone()), ObjKind::Ordinary);
1021	    let aec = vm.native_ctor("AssertionError", 1, assertion_error_ctor, &aep);
1022	    aep.set_prop(PropKey::from_str("name"), Value::str("AssertionError"), WC);
1023	    a.set_prop(PropKey::from_str("AssertionError"), Value::Obj(aec), WEC);
1024	    Value::Obj(a)
1025	}
1026	
1027	fn assertion_error_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
1028	    let msg = match a.arg(0) {
1029	        Value::Obj(o) => vm.get_str(&o, "message")?,
1030	        _ => Value::Undefined,
1031	    };
1032	    let m = if msg.is_undefined() { "Failed".to_string() } else { vm.to_string(&msg)?.to_rust_string() };
1033	    Ok(make_assertion_error(vm, &m, Value::Undefined, Value::Undefined, "fail"))
1034	}
1035	
1036	pub fn make_assertion_error(vm: &mut Vm, msg: &str, actual: Value, expected: Value, op: &str) -> Value {
1037	    let e = vm.make_error("Error", msg);
1038	    if let Value::Obj(o) = &e {
1039	        o.set_prop(PropKey::from_str("name"), Value::str("AssertionError"), WC);
1040	        o.set_prop(PropKey::from_str("generatedMessage"), Value::Bool(false), WEC);
1041	        o.set_prop(PropKey::from_str("code"), Value::str("ERR_ASSERTION"), WEC);
1042	        o.set_prop(PropKey::from_str("actual"), actual, WEC);
1043	        o.set_prop(PropKey::from_str("expected"), expected, WEC);
1044	        o.set_prop(PropKey::from_str("operator"), Value::str(op), WEC);
1045	        vm.attach_stack(o, "AssertionError", msg);
1046	    }
1047	    e
1048	}
1049	
1050	fn assert_ok(vm: &mut Vm, a: &Args) -> JsResult<Value> {
1051	    if a.arg(0).truthy() {
1052	        return Ok(Value::Undefined);
1053	    }
1054	    let m = a.arg(1);
1055	    if let Value::Obj(o) = &m {
1056	        if matches!(o.borrow().kind, ObjKind::Error) {
1057	            return Err(m);
1058	        }
1059	    }
1060	    let msg = if m.is_undefined() {
1061	        if a.args.is_empty() {
1062	            "No value argument passed to `assert.ok()`".to_string()
1063	        } else {
1064	            "The expression evaluated to a falsy value".to_string()
1065	        }
1066	    } else {
1067	        vm.to_string(&m)?.to_rust_string()
1068	    };
1069	    Err(make_assertion_error(vm, &msg, a.arg(0), Value::Bool(true), "=="))
1070	}
1071	
1072	fn assert_cmp(vm: &mut Vm, a: &Args, op: &str) -> JsResult<Value> {
1073	    let x = a.arg(0);
1074	    let y = a.arg(1);
1075	    let ok = match op {
1076	        "==" => vm.loose_eq(&x, &y)? || (matches!((&x, &y), (Value::Num(p), Value::Num(q)) if p.is_nan() && q.is_nan())),
1077	        "!=" => !vm.loose_eq(&x, &y)?,
1078	        "===" => Value::same_value(&x, &y),
1079	        "!==" => !Value::same_value(&x, &y),
1080	        "deepEqual" => deep_equal(vm, &x, &y, false)?,
1081	        "deepStrictEqual" => deep_equal(vm, &x, &y, true)?,
1082	        "notDeepEqual" => !deep_equal(vm, &x, &y, false)?,
1083	        _ => !deep_equal(vm, &x, &y, true)?,
1084	    };
1085	    if ok {
1086	        return Ok(Value::Undefined);
1087	    }
1088	    let m = a.arg(2);
1089	    if let Value::Obj(o) = &m {
1090	        if matches!(o.borrow().kind, ObjKind::Error) {
1091	            return Err(m);
1092	        }
1093	    }
1094	    let msg = if m.is_undefined() {
1095	        let xs = inspect_value(vm, &x, 2)?;
1096	        let ys = inspect_value(vm, &y, 2)?;
1097	        let xs = if let Value::Str(_) = x { format!("'{}'", xs) } else { xs };
1098	        let ys = if let Value::Str(_) = y { format!("'{}'", ys) } else { ys };
1099	        match op {
1100	            "===" => format!("Expected values to be strictly equal:\n\n{} !== {}\n", xs, ys),
1101	            "deepStrictEqual" => format!("Expected values to be strictly deep-equal:\n{} !== {}", xs, ys),
1102	            "!==" => format!("Expected \"actual\" to be strictly unequal to: {}", ys),
1103	            _ => format!("{} {} {}", xs, op, ys),
1104	        }
1105	    } else {
1106	        vm.to_string(&m)?.to_rust_string()
1107	    };
1108	    Err(make_assertion_error(vm, &msg, x, y, op))
1109	}
