1111	fn check_expected_error(vm: &mut Vm, e: &Value, expected: &Value) -> JsResult<bool> {
1112	    match expected {
1113	        Value::Undefined => Ok(true),
1114	        Value::Obj(o) if o.is_callable() => {
1115	            if o.is_constructor() {
1116	                let proto = vm.get_str(o, "prototype")?;
1117	                if proto.is_object() {
1118	                    if vm.instance_of(e, expected)? {
1119	                        return Ok(true);
1120	                    }
1121	                    // error class that doesn't match
1122	                    if let Value::Obj(po) = &proto {
1123	                        let err_proto = vm.intr.error_proto.clone();
1124	                        let mut cur = Some(po.clone());
1125	                        while let Some(c) = cur {
1126	                            if c.ptr_eq(&err_proto) {
1127	                                return Ok(false);
1128	                            }
1129	                            cur = c.borrow().proto.clone();
1130	                        }
1131	                    }
1132	                }
1133	            }
1134	            let r = vm.call(expected, Value::Undefined, &[e.clone()])?;
1135	            Ok(r.truthy())
1136	        }
1137	        Value::Obj(o) if matches!(o.borrow().kind, ObjKind::RegExp(_)) => {
1138	            let s = crate::runtime::display_value(vm, e);
1139	            let t = vm.get_str(o, "test")?;
1140	            Ok(vm.call(&t, expected.clone(), &[Value::str(&s)])?.truthy())
1141	        }
1142	        Value::Obj(o) => {
1143	            let keys = vm.enumerable_own_keys(o)?;
1144	            for k in keys {
1145	                let ev = vm.get_prop_of(e, &PropKey::Str(k.clone()))?;
1146	                let xv = vm.get(o, &PropKey::Str(k), expected)?;
1147	                let ok = if let Value::Obj(xo) = &xv {
1148	                    if matches!(xo.borrow().kind, ObjKind::RegExp(_)) {
1149	                        let s = crate::runtime::display_value(vm, &ev);
1150	                        let t = vm.get_str(xo, "test")?;
1151	                        vm.call(&t, xv.clone(), &[Value::str(&s)])?.truthy()
1152	                    } else {
1153	                        deep_equal(vm, &ev, &xv, true)?
1154	                    }
1155	                } else {
1156	                    deep_equal(vm, &ev, &xv, true)?
1157	                };
1158	                if !ok {
1159	                    return Ok(false);
1160	                }
1161	            }
1162	            Ok(true)
1163	        }
1164	        _ => Ok(true),
1165	    }
1166	}
