1168	fn assert_throws(vm: &mut Vm, a: &Args) -> JsResult<Value> {
1169	    let f = a.arg(0);
1170	    match vm.call(&f, Value::Undefined, &[]) {
1171	        Ok(_) => {
1172	            let m = if let Value::Str(s) = a.arg(1) { s.to_rust_string() } else if let Value::Str(s) = a.arg(2) { s.to_rust_string() } else { String::new() };
1173	            let msg = if m.is_empty() { "Missing expected exception.".to_string() } else { format!("Missing expected exception: {}", m) };
1174	            Err(make_assertion_error(vm, &msg, Value::Undefined, a.arg(1), "throws"))
1175	        }
1176	        Err(e) => {
1177	            let exp = a.arg(1);
1178	            if let Value::Str(_) = exp {
1179	                return Ok(Value::Undefined);
1180	            }
1181	            if check_expected_error(vm, &e, &exp)? {
1182	                Ok(Value::Undefined)
1183	            } else {
1184	                Err(e)
1185	            }
1186	        }
1187	    }
1188	}
