1190	fn assert_does_not_throw(vm: &mut Vm, a: &Args) -> JsResult<Value> {
1191	    match vm.call(&a.arg(0), Value::Undefined, &[]) {
1192	        Ok(_) => Ok(Value::Undefined),
1193	        Err(e) => {
1194	            let mv = vm.get_prop_of(&e, &PropKey::from_str("message")).unwrap_or(Value::Undefined);
1195	            let m = crate::runtime::display_value(vm, &mv);
1196	            Err(make_assertion_error(vm, &format!("Got unwanted exception.\nActual message: \"{}\"", m), e, Value::Undefined, "doesNotThrow"))
1197	        }
1198	    }
