/// `String(v)` (symbols allowed).
fn string_of(vm: &mut Vm, v: &Value) -> JsResult<String> {
    match v {
        Value::Sym(s) => Ok(s.descriptive_string()),
        _ => Ok(vm.to_string(v)?.to_rust_string()),
    }
}

