const util = require('util');
function myers(actual, expected, variant) {
  const n = actual.length, m = expected.length, max = n + m;
  const v = new Array(2 * max + 2).fill(0);
  const trace = [];
  outer: for (let d = 0; d <= max; d++) {
    trace.push(v.slice());
    for (let k = -d; k <= d; k += 2) {
      const o = k + max;
      let x;
      const cond = variant.le ? v[o - 1] <= v[o + 1] : v[o - 1] < v[o + 1];
      if (k === -d || (k !== d && cond)) x = v[o + 1]; else x = v[o - 1] + 1;
      let y = x - k;
      while (x < n && y < m && actual[x] === expected[y]) { x++; y++; }
      v[o] = x;
      if (x >= n && y >= m) break outer;
    }
  }
  let x = n, y = m;
  const res = [];
  for (let d = trace.length - 1; d >= 0; d--) {
    const vv = trace[d];
    const k = x - y, o = k + max;
    const cond = variant.le ? vv[o - 1] <= vv[o + 1] : vv[o - 1] < vv[o + 1];
    const pk = (k === -d || (k !== d && cond)) ? k + 1 : k - 1;
    const px = vv[pk + max], py = px - pk;
    while (x > px && y > py) { res.push([0, actual[x - 1]]); x--; y--; }
    if (d > 0) {
      if (x > px) { res.push([1, actual[x - 1]]); x--; } else { res.push([-1, expected[y - 1]]); y--; }
    }
  }
  return res.reverse();
}
function rev(actual, expected, variant) {
  const r = myers([...actual].reverse(), [...expected].reverse(), variant);
  return r.reverse();
}
const cases = [['aaa', 'aa'], ['abcabba', 'cbabac'], ['kitten', 'sitting'], ['abcd', 'acbd'], ['ab', 'ba'], ['hello world', 'hello there'], ['12345', '2345'], ['abc', 'xyz']];
for (const [a, b] of cases) {
  const want = JSON.stringify(util.diff(a, b));
  const res = {
    fwd: JSON.stringify(myers([...a], [...b], {})),
    fwdle: JSON.stringify(myers([...a], [...b], { le: true })),
    rev: JSON.stringify(rev([...a], [...b], {})),
    revle: JSON.stringify(rev([...a], [...b], { le: true })),
  };
  console.log(a, b, Object.entries(res).filter(([k, v]) => v === want).map(([k]) => k).join(',') || 'NONE');
}

