const util = require('util');
const assert = require('assert');
let seed = Number(process.argv[2] || 1);
function rnd() { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; }
function pick(a) { return a[Math.floor(rnd() * a.length)]; }
const keys = ['a', 'b', 'c', '0', '1'];
function prim() { return pick([0, -0, 1, '1', '', 'a', NaN, null, undefined, true, false, 1n, Infinity]); }
// generate a pair of similar values
function gen(d) {
  const r = rnd();
  if (d > 2 || r < 0.3) return prim();
  const t = Math.floor(rnd() * 10);
  switch (t) {
    case 0: case 1: { const o = {}; const n = Math.floor(rnd() * 3); for (let i = 0; i < n; i++) o[pick(keys)] = gen(d + 1); return o; }
    case 2: case 3: { const a = []; const n = Math.floor(rnd() * 3); for (let i = 0; i < n; i++) a.push(gen(d + 1)); return a; }
    case 4: { const m = new Map(); const n = Math.floor(rnd() * 3); for (let i = 0; i < n; i++) m.set(pick([1, 'a', '1', NaN]), gen(d + 1)); return m; }
    case 5: { const s = new Set(); const n = Math.floor(rnd() * 3); for (let i = 0; i < n; i++) s.add(pick([1, 'a', '1', NaN, 0, -0])); return s; }
    case 6: return pick([new Date(0), new Date(1), /a/, /a/g, new Number(1), new String('a'), new Boolean(false), Object.create(null)]);
    case 7: return new Uint8Array(Math.floor(rnd() * 3));
    case 8: { class C { constructor() { this.a = 1; } } return new C(); }
    default: return pick([new Error('x'), new TypeError('x'), Buffer.from('a')]);
  }
}
function mutate(v, d) {
  if (rnd() < 0.5) return v;
  if (v && typeof v === 'object' && !(v instanceof Date) && !(v instanceof RegExp) && rnd() < 0.7 && d < 3) {
    if (Array.isArray(v)) return v.map(x => mutate(x, d + 1));
